B.am=s([],t.zr)
B.WW=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.Oi=new A.ct("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
B.YG=s([B.Oi],t.u)
