B.X0=s([B.P5],t.J)
B.Or=new A.cM("Player",B.X0)
B.Xr=s(["Then what should I call you?"],t.s)
B.Od=new A.ct("Choose your name","intro_choose_player_name",!0,!1)
B.US=s([B.Od],t.u)
B.P0=new A.cg(B.am,B.Xr,null,null,null,B.US)
B.Um=s([B.P0],t.J)
B.Os=new A.cM("Concerned Stranger",B.Um)
B.Vg=s(["Welcome, captain. Your ship has good bones, but there is always room for finer work.","Would you like to order work on your ship?"],t.s)
B.Oa=new A.ct("View ship upgrades","open_ship_upgrade_menu",!1,!0)
B.Xv=s([B.Oa,B.fX],t.u)
B.OR=new A.cg(B.am,B.Vg,null,null,null,B.Xv)
B.Xg=s([B.OR],t.J)
B.Ot=new A.cM("Shipwright",B.Xg)
B.Wf=s(["The player stirs, violently coughing up seawater. There is a distinct taste of iron admist the saltiness. The chill on your flesh is contrasted by the burning in your side."],t.s)
B.Ob=new A.ct("Next","intro_show_stranger",!0,!1)
B.YU=s([B.Ob],t.u)
B.OU=new A.cg(B.am,B.Wf,null,null,null,B.YU)
B.W7=s([B.OU],t.J)
B.Ou=new A.cM("Narrator",B.W7)
B.WF=s(["I...I...I don't know... I..."],t.s)
B.O6=new A.ct("Try to Remember","intro_show_british_officer",!0,!1)
B.Z1=s([B.O6],t.u)
B.OX=new A.cg(B.am,B.WF,null,null,null,B.Z1)
B.Vu=s([B.OX],t.J)
B.Ov=new A.cM("Player",B.Vu)
B.Yp=s(["I... I cannot remember."],t.s)
B.O7=new A.ct("Continue","intro_ask_player_name",!0,!1)
B.Wn=s([B.O7],t.u)
B.Pf=new A.cg(B.am,B.Yp,null,null,null,B.Wn)
B.VL=s([B.Pf],t.J)
B.Ow=new A.cM("Player",B.VL)
B.Z6=s(["Nothing... apart from a face.","A young man with dark hair and cold eyes. He wore a naval coat finer than any officer's, with a golden lion at his collar.","He looked at me as though he knew me. Then everything went dark."],t.s)
B.NX=new A.ct("Watch Mateo's reaction","intro_mateo_recognizes_prince",!0,!1)
B.YL=s([B.NX],t.u)
B.OZ=new A.cg(B.am,B.Z6,null,null,null,B.YL)
B.Yd=s([B.OZ],t.J)
B.Ox=new A.cM("Player",B.Yd)
B.Vr=s(["That sounds like the Prince of Britain.","The British Navy has been cracking down hard on piracy. If you crossed paths with the prince himself, they may have taken you for a pirate.","But the crown calls everyone a criminal when it suits them. The government is corrupt, and poverty has spread across the nation while the powerful line their own pockets.","Many people down on their luck have turned to piracy simply to make ends meet. For some, it is the only way left to put food on the table."],t.s)
B.dP=s([],t.u)
B.Pc=new A.cg(B.am,B.Vr,null,null,null,B.dP)
B.UU=s([B.Pc],t.J)
B.Oy=new A.cM("Mateo",B.UU)
B.Yl=s(["Welcome to the cafe, captain. You look like you could use something strong after your voyage.","Would you like to browse today's menu of consumables?"],t.s)
B.O_=new A.ct("Browse menu","open_spanish_cafe_menu",!0,!1)
B.UT=s([B.O_,B.fX],t.u)
B.P4=new A.cg(B.am,B.Yl,null,null,null,B.UT)
B.YM=s([B.P4],t.J)
B.Oz=new A.cM("Barista",B.YM)
B.YD=s(["Hey\u2014stay with me. Can you hear me?","Who are you?"],t.s)
B.NW=new A.ct("Try to remember","intro_cannot_remember_name",!0,!1)
B.X3=s([B.NW],t.u)
B.OW=new A.cg(B.am,B.YD,null,null,null,B.X3)
B.Yv=s([B.OW],t.J)
B.OA=new A.cM("Concerned Stranger",B.Yv)
B.YN=s(["The fortress harbor opens, and the Royal Navy sails out to meet you.","Gilded warships spread across the channel beneath British flags, forming a wall between your fleet and the island.","Neither armada turns away."],t.s)
B.P7=new A.cg(B.am,B.YN,null,null,null,B.dP)
B.YF=s([B.P7],t.J)
B.OB=new A.cM("Narrator",B.YF)
B.Wl=s(["The cave trembles as something immense stirs beneath the black water.","A forest of tentacles rises from the depths, and a furious eye fixes upon your crew.","You were a fool to come here."],t.s)
B.Oh=new A.ct("Face the Kraken","start_kraken_fight",!0,!1)
B.Wi=s([B.Oh],t.u)
B.Pg=new A.cg(B.am,B.Wl,null,null,null,B.Wi)
B.Wo=s([B.Pg],t.J)
B.OC=new A.cM("The Kraken",B.Wo)
B.Wq=s(["You close your eyes. The room falls away.","His face emerges from the darkness, framed by drifting smoke: the same cold stare, the same golden insignia."],t.s)
B.Og=new A.ct("Open your eyes","intro_describe_remembered_face",!0,!1)
B.W0=s([B.Og],t.u)
B.P3=new A.cg(B.am,B.Wq,null,null,null,B.W0)
B.Uc=s([B.P3],t.J)
B.OD=new A.cM("Narrator",B.Uc)
B.V0=s(["Thank god... I feared the worst. What happened to you?"],t.s)
B.Oj=new A.ct("Continue","intro_player_remembers",!0,!1)
B.Y1=s([B.Oj],t.u)
B.P6=new A.cg(B.am,B.V0,null,null,null,B.Y1)
B.Ya=s([B.P6],t.J)
B.OE=new A.cM("Stranger",B.Ya)
B.YO=s(["I was on my way to the docks when I found you. I was sure you were dead...","The doctor has been by to check on you. Your body, he says, will heal, but he cannot explain your memory loss.","Now that you are awake, do you remember anything about what happened to you?"],t.s)
B.O9=new A.ct("Try to remember","intro_recall_prince_face",!0,!1)
B.YQ=s([B.O9],t.u)
B.P_=new A.cg(B.am,B.YO,null,null,null,B.YQ)
B.Z2=s([B.P_],t.J)
B.OF=new A.cM("Mateo",B.Z2)
B.Wp=s(["Welcome aboard, sailor. I am Captain Lorenzo, and I assign bounties to crews bold enough to earn them.","A bounty is a promise: I name the target, you bring back proof, and the reward is yours.","I have a first contract waiting. Will you accept it?"],t.s)
B.Oe=new A.ct("Accept first bounty","accept_italy_first_bounty",!0,!0)
B.O4=new A.ct("Not yet","close_dialogue",!0,!0)
